// DataQ marketing — the subset of the app's design-system components the
// landing page actually renders (Button, Card, MetricCard, ProgressBar,
// StatusBadge). Mirrors frontend/src/theme.ts token names; not the app's
// real component library, which lives under frontend/src/.
import React from 'react';

function _extends() {
  return (_extends = Object.assign
    ? Object.assign.bind()
    : function (n) {
        for (var e = 1; e < arguments.length; e++) {
          var t = arguments[e];
          for (var r in t) ({}).hasOwnProperty.call(t, r) && (n[r] = t[r]);
        }
        return n;
      }).apply(null, arguments);
}

/**
 * DataQ Button — the primary interactive control.
 * Variants: primary (solid indigo), secondary (slate outline),
 * ghost (utility, used in tables), danger (destructive).
 */
export function Button({
  children,
  variant = 'primary',
  size = 'md',
  iconLeft = null,
  iconRight = null,
  disabled = false,
  type = 'button',
  onClick,
  style = {},
  ...rest
}) {
  const [hover, setHover] = React.useState(false);
  const [active, setActive] = React.useState(false);
  const sizes = {
    sm: { height: 24, padding: '0 11px', fontSize: 13, gap: 6 },
    md: { height: 32, padding: '0 15px', fontSize: 14, gap: 8 },
    lg: { height: 40, padding: '0 20px', fontSize: 15, gap: 8 },
  };
  const s = sizes[size] || sizes.md;
  const base = {
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: s.gap,
    height: s.height,
    padding: s.padding,
    fontFamily: 'var(--font-sans)',
    fontSize: s.fontSize,
    fontWeight: 600,
    lineHeight: 1,
    borderRadius: 'var(--radius)',
    border: '1px solid transparent',
    cursor: disabled ? 'not-allowed' : 'pointer',
    opacity: disabled ? 0.5 : 1,
    transition: 'background .15s, border-color .15s, box-shadow .15s, transform .05s',
    transform: active && !disabled ? 'translateY(0.5px)' : 'none',
    whiteSpace: 'nowrap',
    boxSizing: 'border-box',
  };
  const variants = {
    primary: {
      background: hover ? 'var(--action-primary-hover)' : 'var(--action-primary)',
      color: 'var(--action-on-primary)',
      boxShadow: hover && !disabled ? 'var(--shadow-ambient)' : 'none',
    },
    secondary: {
      background: hover ? 'var(--action-secondary-hover)' : 'transparent',
      color: 'var(--action-secondary-fg)',
      borderColor: 'var(--action-secondary-border)',
    },
    ghost: {
      background: hover ? 'var(--bg-hover)' : 'transparent',
      color: 'var(--text-accent)',
    },
    danger: {
      background: hover ? 'color-mix(in srgb, var(--red-500) 88%, #000)' : 'var(--red-500)',
      color: '#fff',
    },
  };
  return React.createElement(
    'button',
    _extends(
      {
        type,
        disabled,
        onClick,
        onMouseEnter: () => setHover(true),
        onMouseLeave: () => {
          setHover(false);
          setActive(false);
        },
        onMouseDown: () => setActive(true),
        onMouseUp: () => setActive(false),
        style: { ...base, ...variants[variant], ...style },
      },
      rest
    ),
    iconLeft,
    children,
    iconRight
  );
}

/**
 * DataQ Card — the base container for grouping related content. 1px
 * border, no shadow at rest; gains a soft ambient shadow when
 * `interactive`. Use tone="dark" for navy feature/monitor panels.
 */
export function Card({ children, tone = 'light', interactive = false, padding = 24, style = {}, onClick, ...rest }) {
  const [hover, setHover] = React.useState(false);
  const tones = {
    light: { background: 'var(--bg-card)', color: 'var(--text-body)', border: '1px solid var(--border-default)' },
    dark: { background: 'var(--bg-panel-dark)', color: 'var(--text-on-dark)', border: '1px solid transparent' },
  };
  const t = tones[tone] || tones.light;
  return React.createElement(
    'div',
    _extends(
      {
        onClick,
        onMouseEnter: () => setHover(true),
        onMouseLeave: () => setHover(false),
        style: {
          borderRadius: 'var(--radius-lg)',
          padding,
          boxSizing: 'border-box',
          transition: 'box-shadow .15s, transform .12s',
          cursor: interactive ? 'pointer' : 'default',
          boxShadow: interactive && hover ? 'var(--shadow-ambient)' : 'none',
          transform: interactive && hover ? 'translateY(-1px)' : 'none',
          ...t,
          ...style,
        },
      },
      rest
    ),
    children
  );
}

/**
 * DataQ MetricCard — a KPI tile: label, large value, optional delta
 * trend, an icon, and an optional thin progress track or footnote.
 */
export function MetricCard({
  label,
  value,
  unit,
  delta,
  trend = 'up',
  icon = null,
  progress = null,
  progressTone = 'pass',
  footnote = null,
  tone = 'light',
  style = {},
}) {
  const onDark = tone === 'dark';
  const deltaColor = trend === 'down' ? 'var(--status-fail)' : 'var(--status-pass)';
  const trackTones = { pass: 'var(--status-pass)', warning: 'var(--status-warn)', fail: 'var(--status-fail)' };
  return React.createElement(
    Card,
    { tone, padding: 20, style: { minWidth: 0, height: '100%', display: 'flex', flexDirection: 'column', boxSizing: 'border-box', ...style } },
    React.createElement(
      'div',
      { style: { display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 12 } },
      React.createElement(
        'span',
        { style: { fontFamily: 'var(--font-sans)', fontSize: 14, fontWeight: 500, color: onDark ? 'var(--text-on-dark-dim)' : 'var(--text-secondary)' } },
        label
      ),
      icon && React.createElement('span', { style: { color: onDark ? 'var(--indigo-300)' : 'var(--gray-500)', flex: 'none' } }, icon)
    ),
    React.createElement(
      'div',
      { style: { display: 'flex', alignItems: 'baseline', gap: 8, marginTop: 10, flexWrap: 'wrap' } },
      React.createElement(
        'span',
        { style: { fontFamily: 'var(--font-sans)', fontSize: 30, fontWeight: 700, lineHeight: 1.1, letterSpacing: '-0.02em', color: onDark ? '#fff' : 'var(--text-primary)' } },
        value
      ),
      unit && React.createElement('span', { style: { fontSize: 14, fontWeight: 500, color: onDark ? 'var(--text-on-dark-dim)' : 'var(--text-secondary)' } }, unit),
      delta && React.createElement('span', { style: { fontFamily: 'var(--font-mono)', fontSize: 13, fontWeight: 600, color: deltaColor } }, delta)
    ),
    (progress != null || footnote) &&
      React.createElement(
        'div',
        { style: { marginTop: 'auto', paddingTop: 16 } },
        progress != null &&
          React.createElement(
            'div',
            { style: { height: 4, borderRadius: 999, background: onDark ? 'rgba(255,255,255,0.12)' : 'var(--surface-3)', overflow: 'hidden' } },
            React.createElement('div', {
              style: {
                height: '100%',
                width: `${Math.max(0, Math.min(100, progress))}%`,
                background: trackTones[progressTone] || trackTones.pass,
                borderRadius: 999,
              },
            })
          ),
        footnote &&
          React.createElement(
            'div',
            { style: { marginTop: progress != null ? 10 : 0, fontSize: 12, color: onDark ? 'var(--text-on-dark-dim)' : 'var(--text-muted)' } },
            footnote
          )
      )
  );
}

/**
 * DataQ ProgressBar — a thin (4px) track for health gauges, pass rates
 * and pipeline progress. `indeterminate` animates a running stripe.
 */
export function ProgressBar({ value = 0, tone = 'pass', height = 4, onDark = false, indeterminate = false, style = {} }) {
  const tones = {
    pass: 'var(--status-pass)',
    warning: 'var(--status-warn)',
    fail: 'var(--status-fail)',
    running: 'var(--run-running)',
    neutral: 'var(--gray-400)',
  };
  const fill = tones[tone] || tones.pass;
  const track = onDark ? 'rgba(255,255,255,0.12)' : 'var(--surface-3)';
  return React.createElement(
    'div',
    {
      role: 'progressbar',
      'aria-valuenow': indeterminate ? undefined : value,
      style: { width: '100%', height, background: track, borderRadius: 'var(--radius-full)', overflow: 'hidden', position: 'relative', ...style },
    },
    React.createElement('div', {
      style: {
        height: '100%',
        width: indeterminate ? '40%' : `${Math.max(0, Math.min(100, value))}%`,
        background: fill,
        borderRadius: 'var(--radius-full)',
        transition: 'width .4s ease',
        position: indeterminate ? 'absolute' : 'static',
        animation: indeterminate ? 'dq-indeterminate 1.1s ease-in-out infinite' : 'none',
      },
    }),
    React.createElement('style', null, `@keyframes dq-indeterminate{0%{left:-40%}100%{left:100%}}`)
  );
}

/**
 * DataQ StatusBadge — the "dot + label" pattern from the Results surface.
 * Statuses map to the real DQ model: result-severity (pass/warn/fail/
 * critical/skip/error, ADR 0005/0016) and run-execution (queued/running/
 * succeeded/failed/cancelled) — same colors the app's antd Tags use.
 */
const STATUS = {
  pass: { label: 'pass', color: 'var(--status-pass)', bg: 'var(--status-pass-bg)' },
  warn: { label: 'warn', color: 'var(--status-warn)', bg: 'var(--status-warn-bg)' },
  fail: { label: 'fail', color: 'var(--status-fail)', bg: 'var(--status-fail-bg)' },
  critical: { label: 'critical', color: 'var(--status-critical)', bg: 'var(--status-critical-bg)' },
  skip: { label: 'skip', color: 'var(--status-skip)', bg: 'var(--status-skip-bg)' },
  error: { label: 'error', color: 'var(--status-error)', bg: 'var(--status-error-bg)' },
  queued: { label: 'queued', color: 'var(--run-queued)', bg: 'var(--run-queued-bg)' },
  running: { label: 'running', color: 'var(--run-running)', bg: 'var(--run-running-bg)' },
  succeeded: { label: 'succeeded', color: 'var(--run-succeeded)', bg: 'var(--run-succeeded-bg)' },
  failed: { label: 'failed', color: 'var(--run-failed)', bg: 'var(--run-failed-bg)' },
  cancelled: { label: 'cancelled', color: 'var(--run-cancelled)', bg: 'var(--run-cancelled-bg)' },
  healthy: { label: 'healthy', color: 'var(--status-pass)', bg: 'var(--status-pass-bg)' },
};

export function StatusBadge({ status = 'pass', label, variant = 'plain', pulse = false, style = {} }) {
  const cfg = STATUS[status] || STATUS.pass;
  const text = label || cfg.label;
  const dot = React.createElement('span', {
    style: {
      width: 8,
      height: 8,
      borderRadius: '50%',
      flex: 'none',
      background: variant === 'solid' ? '#fff' : cfg.color,
      boxShadow: pulse ? `0 0 0 3px color-mix(in srgb, ${cfg.color} 22%, transparent)` : 'none',
    },
  });
  if (variant === 'plain') {
    return React.createElement(
      'span',
      { style: { display: 'inline-flex', alignItems: 'center', gap: 7, fontFamily: 'var(--font-sans)', fontSize: 14, fontWeight: 500, color: cfg.color, ...style } },
      dot,
      text
    );
  }
  const filled = variant === 'solid';
  return React.createElement(
    'span',
    {
      style: {
        display: 'inline-flex',
        alignItems: 'center',
        gap: 6,
        height: 22,
        padding: '0 10px',
        borderRadius: 'var(--radius-full)',
        fontFamily: 'var(--font-sans)',
        fontSize: 12,
        fontWeight: 600,
        letterSpacing: '.02em',
        background: filled ? cfg.color : cfg.bg,
        color: filled ? '#fff' : cfg.color,
        ...style,
      },
    },
    dot,
    text
  );
}

// DataQ marketing — top navigation bar. Brand left, links center,
// sign-in + Get Started right. Composes the design system Button.
import { Button } from './design-system.js';

const GITHUB_URL = 'https://github.com/TheurgicDuke771/DataQ';
const DOCS_URL = 'https://theurgicduke771.github.io/DataQ/docs/';

export function MarketingNav() {
  const links = [
    { label: 'Features', href: '#features' },
    { label: 'Docs', href: DOCS_URL },
    { label: 'GitHub', href: GITHUB_URL },
  ];
  return (
    <header
      style={{
        position: 'sticky',
        top: 0,
        zIndex: 50,
        display: 'flex',
        alignItems: 'center',
        gap: 'var(--nav-gap)',
        height: 64,
        padding: 'var(--nav-padding)',
        background: 'rgba(255,255,255,0.85)',
        backdropFilter: 'blur(8px)',
        borderBottom: '1px solid var(--border)',
      }}
    >
      <div style={{ flex: 1, display: 'flex', alignItems: 'center', gap: 'var(--nav-gap)', minWidth: 0 }}>
        <a href="/" style={{ display: 'flex', alignItems: 'center', gap: 10, textDecoration: 'none', flex: 'none' }}>
          <img src="assets/mark.svg" width="28" height="28" alt="" />
          <span style={{ fontFamily: 'var(--font-sans)', fontWeight: 700, fontSize: 18, color: 'var(--ink)', letterSpacing: '-0.01em' }}>DataQ</span>
        </a>
