      <div onClick={(e) => e.stopPropagation()} style={{ position: 'relative', width: '100%', maxWidth: 960 }}>
        <button
          onClick={onClose}
          aria-label="Close demo video"
          style={{
            position: 'absolute',
            top: -44,
            right: 0,
            width: 32,
            height: 32,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
