{
  "name": "dataq-marketing",
  "private": true,
  "version": "1.0.0",
  "description": "DataQ landing page — pre-rendered static build (see #1561).",
  "type": "module",
  "scripts": {
    "build": "node build.mjs"
  },
  "devDependencies": {
    "esbuild": "^0.24.0",
    "react": "^18.3.1",
    "react-dom": "^18.3.1"
  }
}

// Builds the pre-rendered static marketing page into dist/ (#1561 — the
// page previously shipped as an unbuilt, runtime-Babel-transpiling bundle
// with no content for JS-disabled visitors or crawlers).
import { build } from 'esbuild';
import { promises as fs } from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import React from 'react';
import { renderToStaticMarkup } from 'react-dom/server';

const root = path.dirname(fileURLToPath(import.meta.url));
const dist = path.join(root, 'dist');

await fs.rm(dist, { recursive: true, force: true });
await fs.mkdir(dist, { recursive: true });

// 1. Server-side render. `react`/`react-dom` stay external here so this
//    bundle resolves the SAME module instance react-dom/server uses below —
//    two copies of React in one render breaks hooks ("invalid hook call").
const ssrEntry = path.join(dist, '_ssr.mjs');
await build({
  entryPoints: [path.join(root, 'src/app.jsx')],
  bundle: true,
  format: 'esm',
  platform: 'node',
  jsx: 'automatic',
  external: ['react', 'react-dom', 'react-dom/*'],
  outfile: ssrEntry,
});
const { Landing } = await import(pathToFileURL(ssrEntry).href);
const ssrHtml = renderToStaticMarkup(React.createElement(Landing));
await fs.unlink(ssrEntry);

// 2. Browser hydration bundle — real production React, minified, no
//    runtime Babel. Only wires up the "Watch Demo" modal; the rest of the
//    page is already real markup from step 1.
await build({
  entryPoints: [path.join(root, 'src/app.jsx')],
  bundle: true,
  format: 'iife',
  platform: 'browser',
  jsx: 'automatic',
  minify: true,
  define: { 'process.env.NODE_ENV': '"production"' },
  outfile: path.join(dist, 'bundle.js'),
});

// 3. Compose the shell + SSR markup into the shipped index.html.
const shell = await fs.readFile(path.join(root, 'src/shell.html'), 'utf8');
await fs.writeFile(path.join(dist, 'index.html'), shell.replace('<!--SSR-->', ssrHtml));

// 4. Static assets.
await fs.cp(path.join(root, 'assets'), path.join(dist, 'assets'), { recursive: true });
await fs.copyFile(path.join(root, 'tokens.css'), path.join(dist, 'tokens.css'));

console.log(`marketing build complete -> ${path.relative(root, dist)}/`);

