1	/* ── Design tokens (visual-fidelity pass, ADR 0022) ────────────────────────
2	   Semantic CSS custom properties mirroring the `BRAND` palette in theme.ts.
3	   The app's antd theme reads the JS `BRAND`; these are the CSS-layer twin so
4	   raw CSS rules below (focus ring, elevation, motion) key off the same names.
5	   Keeping them semantic means a post-v1 dark theme can override this one block
6	   (e.g. `:root[data-theme='dark']`) and the whole CSS layer inherits for free. */
7	:root {
8	  --dq-primary: #4f46e5; /* indigo-600 — accents, focus ring */
9	  --dq-primary-soft: #c7d2fe;
10	  --dq-selected-bg: #eef0fe; /* the "selected" fill (nav / active row) */
11	  --dq-row-hover: rgba(79, 70, 229, 0.04); /* a fainter hover tint, distinct from selected */
12	  --dq-canvas: #f4f5f7;
13	  --dq-border: #e6e8eb;
14	  --dq-ink: #1f2430;
15	
16	  /* Elevation — resting + interactive-hover (depth without heavy borders). */
17	  --dq-shadow-rest: 0 1px 3px rgba(16, 24, 40, 0.06);
18	  --dq-shadow-hover: 0 8px 20px rgba(16, 24, 40, 0.1);
19	
20	  /* Motion — 120–180ms eases on bg/border/shadow; a 0.5px press nudge. The
21	     base ease matches antd's standard motion curve so ours don't read foreign. */
22	  --dq-ease: cubic-bezier(0.4, 0, 0.2, 1);
23	  --dq-motion-fast: 120ms;
24	  --dq-motion-base: 160ms;
25	}
26	
27	html,
28	body,
29	#root {
30	  height: 100%;
31	  margin: 0;
32	}
33	
34	body {
35	  font-family:
36	    'Inter',
