48	/* ── Focus ring ────────────────────────────────────────────────────────────
49	   A 2px indigo ring on keyboard focus only (`:focus-visible`, so a mouse click
50	   doesn't draw it), offset just outside the element. Scoped to links and our
51	   custom clickable surfaces — antd form controls / buttons already draw their
52	   own (primary-coloured) focus ring, so a global rule would double-ring them.
53	   No border-radius here — browsers round the outline to each element's own
54	   radius automatically (design 'Focus' guideline). */
55	a:focus-visible,
56	.dq-card--interactive:focus-visible,
57	.dq-suite-row:focus-visible {
58	  outline: 2px solid var(--dq-primary);
59	  outline-offset: 2px;
60	}
61	
62	/* ── Elevation + motion on cards ───────────────────────────────────────────
63	   Gentle resting elevation so white cards lift off the gray canvas rather than
64	   reading as flat panels. */
65	.ant-card {
66	  box-shadow: var(--dq-shadow-rest);
67	}
68	
69	/* Interactive cards (e.g. a connection) lift and deepen their shadow on hover,
70	   with a short ease so it feels responsive, not animated-for-its-own-sake. */
71	.dq-card--interactive {
72	  transition:
73	    box-shadow var(--dq-motion-base) var(--dq-ease),
74	    transform var(--dq-motion-base) var(--dq-ease);
75	}
76	.dq-card--interactive:hover {
77	  transform: translateY(-2px);
78	  box-shadow: var(--dq-shadow-hover);
79	}
80	/* A small press nudge on click closes the loop between hover-lift and action. */
81	.dq-card--interactive:active {
82	  transform: translateY(0.5px);
83	}
84	
85	/* Clickable suite list rows get a hover tint so they read as interactive (the
86	   card grid lifts; the rows can't lift, so a subtle background does the job). */
87	.dq-suite-row {
88	  transition: background var(--dq-motion-fast) var(--dq-ease);
89	}
90	.dq-suite-row:hover {
91	  /* A fainter tint than --dq-selected-bg so "hovering" stays visually distinct
92	     from "selected" (the prior 4% indigo, now tokenised). */
93	  background: var(--dq-row-hover);
94	}
95	
96	/* Buttons get the same 0.5px press nudge — a tactile confirmation of the click.
97	   No `transition` declared on `.ant-btn`: that would clobber antd's own button
98	   transition (CSS `transition` isn't additive) and make hover colour changes
99	   snap. A 0.5px nudge is imperceptible enough to apply instantly on press.
100	   Excludes loading buttons (loading ≠ disabled in antd — pointer-events stay
101	   on) so an in-flight action doesn't bounce and read as still-clickable. */
102	.ant-btn:not(.ant-btn-loading):active {
103	  transform: translateY(0.5px);
104	}
105	
106	/* ── Print (PDF report export, #345) ──────────────────────────────────────
107	   The run-detail page renders two parallel trees: the normal interactive
108	   view (`.no-print`) and a static, chrome-free report (`.print-only`, see
109	   `RunReport.tsx`). "Download → Print / Save as PDF" is just `window.print()`
110	   — the browser's own print-to-PDF is the whole export mechanism, so this
111	   stylesheet is the entire client cost (zero new dependency). Outside a print
112	   context `.print-only` stays out of flow entirely so it never affects layout
113	   or is reachable by assistive tech browsing the page normally. */
114	.print-only {
115	  display: none;
116	}
