import { theme as antdTheme, type ThemeConfig } from 'antd';

/** App-wide Ant Design theme. */

export const BRAND = {
  /** Indigo-600 — the primary accent (buttons, active nav, links). */
  primary: '#4f46e5',
  /** Indigo-200 — the logo's light lobe + the watermark tint. */
  primarySoft: '#c7d2fe',
  /** Pale indigo — the "selected" row/nav background (one tint everywhere). */
  selectedBg: '#eef0fe',
  /** The soft canvas behind white surfaces. */
  canvas: '#f4f5f7',
  /** Hairline border for header / sider / cards. */
  border: '#e6e8eb',
  /** Primary text. */
  ink: '#1f2430',
} as const;

/** Dark-mode counterpart of BRAND (#1562). */
export const DARK_BRAND = {
  primary: '#818cf8',
  primarySoft: '#3730a3',
  selectedBg: 'rgba(129, 140, 248, 0.16)',
  canvas: '#0d1117',
  border: '#30363d',
  ink: '#e6edf3',
} as const;

/** Shared shell metrics so App.tsx and the theme agree. */
export const SHELL = {
  headerHeight: 56,
  siderWidth: 220,
} as const;

/** Shared good/warning/bad/neutral scale — antd's green-6/gold-6/red-6/gray-5. */
export const SEVERITY_SCALE = {
  good: '#52c41a',
  warning: '#faad14',
  bad: '#ff4d4f',
  neutral: '#bfbfbf',
} as const;

export type AppThemeMode = 'light' | 'dark';

export function getAppTheme(mode: AppThemeMode): ThemeConfig {
  const brand = mode === 'dark' ? DARK_BRAND : BRAND;
  const surfaceBg = mode === 'dark' ? '#161b22' : '#ffffff';
  const tableHeaderBg = mode === 'dark' ? '#161b22' : '#fafbfc';

  return {
    algorithm: mode === 'dark' ? antdTheme.darkAlgorithm : antdTheme.defaultAlgorithm,
    token: {
      colorPrimary: brand.primary,
      colorInfo: brand.primary,
      colorLink: brand.primary,
      colorTextHeading: brand.ink,
      colorBgLayout: brand.canvas,
      borderRadius: 8,
      fontFamily:
        "'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif",
      // Code / SQL / identifiers — JetBrains Mono (self-hosted via @fontsource),
      // falling back to the platform monospace stack.
      fontFamilyCode:
        "'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, Consolas, 'Liberation Mono', monospace",
      fontSize: 14,
    },
    components: {
      Layout: {
        headerBg: surfaceBg,
        headerHeight: SHELL.headerHeight,
        headerPadding: '0 24px',
        siderBg: surfaceBg,
        bodyBg: brand.canvas,
      },
      Menu: {
        // Rounded, inset nav items read as a modern sidebar rather than full-bleed rows.
        itemBorderRadius: 8,
        itemMarginInline: 8,
        itemHeight: 38,
        itemSelectedBg: brand.selectedBg,
        itemSelectedColor: brand.primary,
      },
      Card: {
        borderRadiusLG: 12,
      },
      Table: {
        headerBg: tableHeaderBg,
      },
    },
  };
}

import { createContext, useContext, useEffect, useMemo, useState, type ReactNode } from 'react';

export type ThemeModePreference = 'light' | 'dark' | 'system';
export type ResolvedThemeMode = 'light' | 'dark';

const STORAGE_KEY = 'dq-theme-mode';

interface ThemeModeContextValue {
  mode: ThemeModePreference;
  resolvedMode: ResolvedThemeMode;
  setMode: (mode: ThemeModePreference) => void;
}

const ThemeModeContext = createContext<ThemeModeContextValue | null>(null);

function readStoredMode(): ThemeModePreference {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored === 'light' || stored === 'dark' || stored === 'system') return stored;
  } catch {
    // localStorage unavailable (private browsing, disabled) — fall back below.
  }
  return 'system';
}

function systemPrefersDark(): boolean {
  return window.matchMedia('(prefers-color-scheme: dark)').matches;
}

export function ThemeModeProvider({ children }: { children: ReactNode }) {
  const [mode, setModeState] = useState<ThemeModePreference>(readStoredMode);
  const [systemDark, setSystemDark] = useState(systemPrefersDark);

  useEffect(() => {
    const mql = window.matchMedia('(prefers-color-scheme: dark)');
    const onChange = (e: MediaQueryListEvent) => setSystemDark(e.matches);
    mql.addEventListener('change', onChange);
    return () => mql.removeEventListener('change', onChange);
  }, []);

  const resolvedMode: ResolvedThemeMode = mode === 'system' ? (systemDark ? 'dark' : 'light') : mode;

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', resolvedMode);
  }, [resolvedMode]);

  function setMode(next: ThemeModePreference) {
    setModeState(next);
    try {
      localStorage.setItem(STORAGE_KEY, next);
    } catch {
      // Best-effort persistence — the in-memory mode still applies this session.
    }
  }

  const value = useMemo(() => ({ mode, resolvedMode, setMode }), [mode, resolvedMode]);

  return <ThemeModeContext.Provider value={value}>{children}</ThemeModeContext.Provider>;
}

export function useThemeMode(): ThemeModeContextValue {
  const ctx = useContext(ThemeModeContext);
  if (!ctx) throw new Error('useThemeMode must be used within a ThemeModeProvider');
  return ctx;
}

