import { StrictMode, useMemo } from 'react';
import { createRoot } from 'react-dom/client';
import { App as AntApp, ConfigProvider } from 'antd';
import { BrowserRouter } from 'react-router-dom';

import { App } from './App';
import { AuthProvider } from './auth/AuthProvider';
import { CurrentUserProvider } from './auth/CurrentUserProvider';
import { MeProvider } from './auth/MeProvider';
import { OtpSessionProvider } from './auth/OtpSessionProvider';
import { completeSigninIfCallback } from './auth/authClient';
import { ErrorBoundary } from './components/ErrorBoundary';
import { getAppTheme } from './theme';
import { ThemeModeProvider, useThemeMode } from './theme/ThemeModeProvider';

function ThemedShell() {
  const { resolvedMode } = useThemeMode();
  const theme = useMemo(() => getAppTheme(resolvedMode), [resolvedMode]);
  return (
    <ConfigProvider theme={theme}>
      <AntApp>
        <ErrorBoundary>
          <AuthProvider>
            {/* OTP session (ADR 0032) — above CurrentUserProvider, which derives
                the signed-in user from it in `otp` mode. A passthrough in every
                other mode, so no /me probe races the OIDC token acquisition. */}
            <OtpSessionProvider>
              <CurrentUserProvider>
                <MeProvider>
                  <BrowserRouter>
                    <App />
                  </BrowserRouter>
                </MeProvider>
              </CurrentUserProvider>
            </OtpSessionProvider>
          </AuthProvider>
        </ErrorBoundary>
      </AntApp>
    </ConfigProvider>
  );
}

async function bootstrap() {
  await completeSigninIfCallback();
  createRoot(rootEl).render(
    <StrictMode>
      <ThemeModeProvider>
        <ThemedShell />
      </ThemeModeProvider>
    </StrictMode>,
  );
}

